import React, {useState, useEffect, useCallback, memo} from "react";
import PropTypes from "prop-types";
import { TimerWrapper, TimerDisplay } from "./Timer.style";
import { Button } from '../Button/Button';



export const Timer = memo (() => {
    const [time, setTime] = useState(0);
    const [isActive, setIsActive] = useState(false);

    // Обработчик изменения времени
    const incrementTime = useCallback(() => {
        setTime(prevTime => prevTime + 100); // Увеличиваем время на 100 мс
    }, []);

    // Используем useEffect для запуска таймера
    useEffect(() => {
        let timer: NodeJS.Timeout;
        if (isActive) {
            timer = setInterval(incrementTime, 100); // Запускаем таймер
        }
        return () => clearInterval(timer); // Очищаем таймер при размонтировании или паузе
    }, [isActive, incrementTime]);

    // Форматирование времени
    const formatTime = useCallback(() => {
        const minutes = Math.floor((time / 1000 / 60) % 60);
        const seconds = Math.floor((time / 1000) % 60);
        const milliseconds = Math.floor((time % 1000) / 10);
        return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(milliseconds).padStart(2, '0')}`;
    }, [time]);

    return (
        <TimerWrapper>
            <TimerDisplay>{formatTime()}</TimerDisplay>
            <Button onClick={() => setIsActive(prev => !prev)}>
                {isActive ? 'Пауза': 'Запустить'}
            </Button>
            <Button onClick={() => {setIsActive(false); setTime(0)}}>
Сброс
            </Button>
        </TimerWrapper>
    );
});
